package vn.edu.ltweb.jwtmvc.security;
import com.nimbusds.jose.*; import com.nimbusds.jose.crypto.*; import com.nimbusds.jwt.*; import org.springframework.beans.factory.annotation.*; import org.springframework.core.io.Resource; import org.springframework.stereotype.Service; import java.io.*; import java.security.*; import java.security.interfaces.*; import java.security.spec.*; import java.time.*; import java.util.*;
@Service public class NimbusRs256TokenService implements TokenService {private final RSAPrivateKey privateKey;private final RSAPublicKey publicKey;private final String issuer;private final long expiry;
 public NimbusRs256TokenService(@Value("${security.jwt.private-key-path}")Resource priv,@Value("${security.jwt.public-key-path}")Resource pub,@Value("${security.jwt.issuer}")String i,@Value("${security.jwt.expiration-seconds}")long e){try{privateKey=(RSAPrivateKey)KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(read(priv)));publicKey=(RSAPublicKey)KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(read(pub)));}catch(Exception x){throw new IllegalStateException("Cannot load RSA keys",x);}issuer=i;expiry=e;}
 private byte[] read(Resource r)throws IOException{return Base64.getDecoder().decode(new String(r.getInputStream().readAllBytes()).replaceAll("-----BEGIN [A-Z ]+-----|-----END [A-Z ]+-----|\\s", ""));}
 public String issue(String subject){try{Instant n=Instant.now();JWTClaimsSet c=new JWTClaimsSet.Builder().subject(subject).issuer(issuer).issueTime(Date.from(n)).expirationTime(Date.from(n.plusSeconds(expiry))).jwtID(UUID.randomUUID().toString()).build();SignedJWT j=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).type(JOSEObjectType.JWT).build(),c);j.sign(new RSASSASigner(privateKey));return j.serialize();}catch(JOSEException e){throw new IllegalStateException(e);}}
 private JWTClaimsSet claims(String token){try{SignedJWT j=SignedJWT.parse(token);if(!JWSAlgorithm.RS256.equals(j.getHeader().getAlgorithm())||!j.verify(new RSASSAVerifier(publicKey)))throw new TokenValidationException();JWTClaimsSet c=j.getJWTClaimsSet();if(!issuer.equals(c.getIssuer())||c.getSubject()==null||c.getJWTID()==null||c.getExpirationTime()==null||!c.getExpirationTime().after(new Date()))throw new TokenValidationException();return c;}catch(Exception e){if(e instanceof TokenValidationException t)throw t;throw new TokenValidationException(e);}}
 public String extractSubject(String t){return claims(t).getSubject();}public void validate(String t){claims(t);}}
